from typing import Dict, List, Sequence, Tuple
from stockflow.first_fit_decreasing import first_fit_decreasing


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be positive")

    merged_weights: Dict[str, int] = {}
    merged_qtys: Dict[str, int] = {}

    for sku, qty, weight in lines:
        if qty <= 0 or weight <= 0:
            raise ValueError("qty and unit weight must be positive")
        if sku in merged_weights and merged_weights[sku] != weight:
            raise ValueError(f"SKU {sku} has inconsistent unit weights")
        merged_weights[sku] = weight
        merged_qtys[sku] = merged_qtys.get(sku, 0) + qty

    items_for_ffd = []
    block_map = {}
    block_id_counter = 0

    # To satisfy 'lines stay together', we process each SKU
    # and create blocks of the maximum size that fits in a parcel.
    for sku, qty in merged_qtys.items():
        unit_weight = merged_weights[sku]
        if unit_weight > max_parcel_grams:
            raise ValueError(f"Single unit of {sku} exceeds max_parcel_grams")

        units_per_block = max_parcel_grams // unit_weight
        remaining_qty = qty
        while remaining_qty > 0:
            take = min(remaining_qty, units_per_block)
            block_weight = take * unit_weight
            b_id = f"{sku}_{block_id_counter}"
            items_for_ffd.append((b_id, block_weight))
            block_map[b_id] = (sku, take)
            block_id_counter += 1
            remaining_qty -= take

    # first_fit_decreasing sorts by weight DESC, then ID ASC
    bins = first_fit_decreasing(items_for_ffd, max_parcel_grams)

    result = []
    for bin_items in bins:
        parcel = {}
        for b_id, _ in bin_items:
            sku, take = block_map[b_id]
            parcel[sku] = parcel.get(sku, 0) + take
        result.append(parcel)

    return result
"}}}
